from pkg_resources import working_set

def dependency_report(names: list[str]) -> dict[str, str | None]:
    dist_map = {dist.project_name.lower(): dist.version for dist in working_set}
    result = {}
    for name in names:
        version = dist_map.get(name.lower())
        result[name] = version if version is not None else None
    return result

