from marshmallow import Schema, fields, validates, ValidationError, INCLUDE


class SignupSchema(Schema):
    username = fields.Str(required=True)
    email = fields.Email(required=True)
    plan = fields.Str(missing="free")
    age = fields.Int()

    class Meta:
        unknown = INCLUDE  # We will manually drop unknown keys after validation

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric")

    @validates("plan")
    def validate_plan(self, value):
        if value not in {"free", "pro", "team"}:
            raise ValidationError('Plan must be one of "free", "pro", "team"')

    @validates("age")
    def validate_age(self, value):
        if not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120 inclusive")


def validate_signup(data: dict) -> dict:
    schema = SignupSchema()
    try:
        loaded = schema.load(data)
    except ValidationError as err:
        # err.messages is a dict mapping field names to list of error messages
        # Raise ValueError with messages attribute
        exc = ValueError("Invalid input")
        exc.messages = err.messages
        raise exc
    # Drop unknown keys (keys not in schema fields)
    cleaned = {k: v for k, v in loaded.items() if k in schema.fields}
    return cleaned

