from typing import list, dict, Optional
import pkg_resources


def dependency_report(names: list[str]) -> dict[str, Optional[str]]:
    """Return a mapping of given distribution names to their installed version strings or None if not installed.

    The lookup is case-insensitive but the keys in the returned dict preserve the original casing.
    """
    # Build a mapping of lowercase distribution names to their version strings
    installed_versions = {
        dist.project_name.lower(): dist.version
        for dist in pkg_resources.working_set
    }

    result: dict[str, Optional[str]] = {}
    for name in names:
        version = installed_versions.get(name.lower())
        result[name] = version

    return result

