from marshmallow import Schema, fields, ValidationError, validates, validates_schema


class SignupSchema(Schema):
    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer(load_default=None, allow_none=True)

    @validates("username")
    def validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Must be alphanumeric")

    @validates("plan")
    def validate_plan(self, value: str) -> None:
        if value not in {"free", "pro", "team"}:
            raise ValidationError("Must be one of 'free', 'pro', 'team'")

    @validates("age")
    def validate_age(self, value: int) -> None:
        if value is not None and not (16 <= value <= 120):
            raise ValidationError("Must be between 16 and 120 inclusive")

    @validates_schema
    def remove_unknown_fields(self, data, **kwargs):
        # marshmallow 4 does not support unknown=EXCLUDE as a Meta option by default,
        # so we filter unknown keys here by returning only declared fields.
        allowed_fields = set(self.fields.keys())
        keys_to_remove = set(data.keys()) - allowed_fields
        for key in keys_to_remove:
            data.pop(key)
        return data


def validate_signup(data: dict) -> dict:
    schema = SignupSchema()
    try:
        # load() validates and deserializes, applying defaults and removing unknown keys
        result = schema.load(data)
        # If age was not provided, it will be None, remove it from result to keep only required/optional fields
        if result.get("age") is None:
            result.pop("age")
        return result
    except ValidationError as err:
        # Raise ValueError with messages attribute as required
        exc = ValueError("Invalid input")
        exc.messages = err.messages
        raise exc
